<template>
    <div class="layout-px-spacing">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Activity Status</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>

            <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="unit_registration =! unit_registration">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>  

           
 <!-- item registration form starts -->
 <form v-if="unit_registration" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerActivityStatus">
        <h4 class="text-center">ACTIVITY STATUS REGISTRATION FORM</h4>
        <div class="row mb-2">
    
            <div class="col-md-3">
                <label class="form-label">Name</label>
                <input type="text" class="form-control" placeholder="Enter Name" v-model="name" required>
            </div>

            <div class="col-md-3">
                <label class="form-label">Description</label>
                <input type="text" class="form-control" placeholder="Enter Description" v-model="description">
            </div>
            <div class="col-md-3">
                <label class="form-label">start_time</label>
                <input type="time" class="form-control" placeholder="Enter start_time" v-model="start_time">
            </div>
            <div class="col-md-3">
                <label class="form-label">end_time</label>
                <input type="time" class="form-control" placeholder="Enter end_time" v-model="end_time">
            </div>
        </div>
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="unit_registration = false; resetForm();">Cancel</button>
            <button type="submit" class="btn btn-primary">Register</button>
        </div>
    </form>
             <!-- item registration form ends-->
      
        <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
                        <v-client-table v-else :data="units" :columns="columns" :options="table_option">
                            <template #status="props">
                                <span class="badge" :class="props.row.status === 'open' ? 'bg-success' : 'bg-danger'">
                                    {{ props.row.status }}
                                </span>
                            </template>
                            <template #actions="props">
                                <div class ="d-flex justfy-content-center align-items-center">
                                    <a href="javascript:;" class="edit me-3" @click="edit_row(props.row)">
                                            <svg
                                                xmlns="http://www.w3.org/2000/svg"
                                                width="24"
                                                height="24"
                                                viewBox="0 0 24 24"
                                                fill="none"
                                                stroke="currentColor"
                                                stroke-width="1.5"
                                                stroke-linecap="round"
                                                stroke-linejoin="round"
                                                class="text-primary"
                                                data-bs-toggle="modal" 
                                                data-bs-target="#edit-modal"
                                            >
                                                <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                                                <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                                            </svg>
                                        </a>
                                <a href="javascript:;" class="cancel" @click="delete_row(props.row)" v-if="user_permissions.includes('can_delete_module_status')">
                                            <svg
                                            xmlns="http://www.w3.org/2000/svg"
                                            width="24"
                                            height="24"
                                            viewBox="0 0 24 24"
                                            fill="none"
                                            stroke="currentColor"
                                            stroke-width="1.5"
                                            stroke-linecap="round"
                                            stroke-linejoin="round"
                                            class="text-danger"
                                        >
                                            <polyline points="3 6 5 6 21 6"></polyline>
                                            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                                        </svg>
                                        </a>
                                        </div>
                                
                            </template>
                           <template #footer>
                               <div class="modal-footer">
                                   <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
                                   <button type="button" class="btn btn-primary" @click="save_edit" :disabled="isSaving" >Save changes</button>
                               </div>
                           </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>


 <!-- Edit Labour Modal -->
<div class="modal fade mymodal" id="edit-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editModalLabel">Edit Activity Status</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closeEditModal()"></button>
      </div>
      <form @submit.prevent=" save_edit()">
        <div class="modal-body">
            <div class="row">
            <div class="col-md-4">
                <label for="name">Name</label>
              <input type="text" v-model="name" class="form-control" placeholder="Enter Name" >
            </div>
            <div class="col-md-4">
                <label for="description">Description</label>
              <input type="text" v-model="description" class="form-control" placeholder="Description" >
            </div>
                        <div class="col-md-4">
                <label for="description">Start Time</label>
              <input type="time" v-model="start_time" class="form-control" placeholder="Description" >
            </div>
                        <div class="col-md-4">
                <label for="description">End Time</label>
              <input type="time" v-model="end_time" class="form-control" placeholder="Description" >
            </div>

            <div 
        class="col-md-4">
            <label for="Status">Status</label>
            <multiselect 
                v-model="status"
                :options= "['open','closed']"
                placeholder="Select Status"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
        </div>
          <div 
        class="col-md-4">
            <label for="Status">Always Open</label>
            <select class="form-control" v-model="always_open" required>
                <option value=1>YES</option>
                <option value=0>NO</option>
            </select>
        </div>


          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_modal" >Close</button>
          <button type="submit" class="btn btn-primary">
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>



   </div>
</template>

<script setup>
    import { onMounted, ref,inject,computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
import { start } from '@popperjs/core';
    useMeta({ title: 'Custom Table' });

    const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    
    const tableShimmer = inject('tableShimmer');
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const showConfirmation = inject('showConfirmation');
    const editingRow = ref({});
    const name = ref('');
    const description = ref('');
    const status = ref('');
    const start_time = ref('');
    const end_time = ref('');
    const loading_spinner = ref(false);
    const columns = ref(['SNo', 'name', 'description','start_time','end_time', 'status', 'actions']);
    const units = ref([]);
    const unit_registration = ref(false);
    const table_option = ref({
        perPage: 10,
        perPageValues: [10, 20, 50],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const getActivityStatuses = async () => {
  loading_spinner.value = true;

  try {
    const response = await axiosInstance.get('/activity-statuses');
    units.value = response.data.map((item, index) => ({
        ...item,
      SNo: index + 1,
    }));
  } catch (error) {
    showError(error.message);
  } finally {
    loading_spinner.value = false;
  }
};


    const registerActivityStatus = () => {
        unit_registration.value = false;
        loading_spinner.value = true;
        const itemData = {
            name: name.value,
            description: description.value,
            start_time:start_time.value,
            end_time:end_time.value
        };
        axiosInstance
            .post('/activity-statuses', itemData)
            .then((response) => {
                getActivityStatuses();
                loading_spinner.value = false;
                showMessage('Activity Status registered successfully!');
                resetForm();
                if (response.data.status === 201) {
                } 
            })
            .catch((error) => {
                showError(error.message);
            });
    };


const delete_row = async (row) => {
showConfirmation('Delete Module Status','Are you sure to delete ' + row.name +' module?' ,`activity-statuses/${row.id}`,'delete')
};


    const always_open = ref('')
    const edit_row = (row) => {
        editingRow.value = { ...row }; 
        name.value = row.name;
        description.value = row.description;
        status.value = row.status;
        start_time.value = row.start_time,
        end_time.value = row.end_time,
        always_open.value = row.infinity_open
        start_time.value = row.start_time;
        end_time.value = row.end_time;
    };

    const save_edit = async () => {
        loading_spinner.value = true;
    const payloaad = {
        name: name.value,
        description: description.value,
        start_time:start_time.value,
        end_time:end_time.value,
        status: status.value,
        start_time : start_time.value,
        end_time :end_time.value,
        infinity_open : always_open.value
    };
        try {
            const response = await axiosInstance.put(`/activity-statuses/${editingRow.value.id}`, payloaad);
            if (response.status === 200) {
                showMessage('Activity Status updated successfully!');
                getActivityStatuses();
                document.getElementById('close_modal').click();
            }
           
        } catch (error) {
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
      
    }; 

    const resetForm = () => {
    name.value = '';
    description.value = '';
};

const closeEditModal = () => {
    resetForm();
};

    onMounted(() => {
        getActivityStatuses();
    });
</script>

